# Catechism bank — the mabnī Q&A (research/sources/mensubat.txt, fourth section, items 1-22).
ITEMS = [
 {"n": 1, "q": {"tr": "Mebnînin tarifi nedir? Mebnî asıllar nelerdir?", "en": "How is the built word defined, and what are the originally-built?"},
  "a": {"tr": "Mebnî asla benzeyen ya da terkipsiz vâki olandır. Mebnî asıllar dörttür: harf, fiil-i mâzî, lâm'sız emir, cümle.", "en": "What resembles the originally-built, or occurs outside any compound. The originally-built are four: the particle, the past verb, the imperative without the lām, and the sentence."},
  "ar": ["مَا نَاسَبَ مَبْنِيَّ الْأَصْلِ أَوْ وَقَعَ غَيْرَ مُرَكَّبٍ"], "notes": ["al-mabni-wal-mudmar", "al-murab-wal-mabni-wal-irab"], "story": "al-kafiya", "chapter": 3},
 {"n": 2, "q": {"tr": "Mebnînin lakapları nelerdir?", "en": "What are the names of the built word's endings?"},
  "a": {"tr": "Dörttür: damme, fetha, kesre, vakıf.", "en": "Four: ḍamma, fatḥa, kasra and pause (sukūn)."},
  "ar": [], "notes": ["al-mabni-wal-mudmar", "al-taqdiri-al-sabi-wal-mahalli-wal-mabni-wa-aqsamuh"]},
 {"n": 3, "q": {"tr": "Mebnînin hükmü nedir? Mebnî isimler kaçtır, nelerdir?", "en": "What is the ruling of the built word, and how many built nouns are there?"},
  "a": {"tr": "Hükmü, âmillerin değişmesiyle sonunun değişmemesidir. Mebnî isimler dokuzdur: zamirler, işaret isimleri, mevsûller, mürekkepler, kinâyeler, isim-fiiller, sesler, bazı zarflar (ve mabniyye'nin diğerleri).",
        "en": "Its ruling: its ending does not change as the governors change. The built nouns are nine: the pronouns, the demonstratives, the relatives, the compounds, the allusive nouns (kināyāt), the noun-verbs, the sounds, and some of the adverbs."},
  "ar": [], "notes": ["al-mabni-wal-mudmar", "al-mabni-al-lazim-al-mudmarat-wal-isharat-wal-mawsulat-wa-faali-wal-aswat-wal-murakkab"], "story": "al-kafiya", "chapter": 3},
 {"n": 4, "q": {"tr": "Zamirin tarifi nedir?", "en": "How is the pronoun defined?"},
  "a": {"tr": "Mütekellim, muhâtab ya da zikri lafzan, mânen ya da hükmen önce geçmiş gâib için konulan şeydir.", "en": "What is coined for the speaker, the addressee, or an absent one whose mention has gone before in wording, in meaning or in ruling."},
  "ar": ["مَا وُضِعَ لِمُتَكَلِّمٍ أَوْ مُخَاطَبٍ أَوْ غَائِبٍ تَقَدَّمَ ذِكْرُهُ لَفْظًا أَوْ مَعْنًى أَوْ حُكْمًا"], "notes": ["al-mabni-wal-mudmar", "al-marifa-al-mudmarat-wal-alam"], "story": "al-kafiya", "chapter": 3},
 {"n": 5, "q": {"tr": "Zamirler kaç kısımdır?", "en": "How many kinds of pronoun are there?"},
  "a": {"tr": "Öncesine göre muttasıl ve munfasıl; i'râba göre merfû, mansûb, mecrûr. Böylece beş nev': merfû muttasıl (ضَرَبْتُ … ضَرَبْنَ), merfû munfasıl (أَنَا … هُنَّ), mansûb muttasıl (fiile: ضَرَبَنِي … ضَرَبَهُنَّ; harfe: إِنَّنِي … إِنَّهُنَّ), mansûb munfasıl (إِيَّايَ … إِيَّاهُنَّ), mecrûr muttasıl (isme: غُلَامِي … غُلَامِهِنَّ; harfe: لِي … لَهُنَّ).",
        "en": "By what precedes, attached and detached; by case, rafʿ, naṣb, jarr — five kinds: attached rafʿ (ضَرَبْتُ … ضَرَبْنَ), detached rafʿ (أَنَا … هُنَّ), attached naṣb (to a verb ضَرَبَنِي … ضَرَبَهُنَّ, to a particle إِنَّنِي … إِنَّهُنَّ), detached naṣb (إِيَّايَ … إِيَّاهُنَّ), attached jarr (to a noun غُلَامِي … غُلَامِهِنَّ, to a particle لِي … لَهُنَّ)."},
  "ar": ["أَنَا نَحْنُ أَنْتَ أَنْتُمَا أَنْتُمْ أَنْتِ أَنْتُمَا أَنْتُنَّ هُوَ هُمَا هُمْ هِيَ هُمَا هُنَّ", "إِيَّايَ إِيَّانَا إِيَّاكَ إِيَّاكُمَا إِيَّاكُمْ إِيَّاكِ إِيَّاكُمَا إِيَّاكُنَّ إِيَّاهُ إِيَّاهُمَا إِيَّاهُمْ إِيَّاهَا إِيَّاهُمَا إِيَّاهُنَّ"], "notes": ["al-mabni-wal-mudmar", "al-bariz-al-muttasil"], "story": "al-kafiya", "chapter": 3},
 {"n": 6, "q": {"tr": "Merfû muttasıl zamirler kaç kısımdır? Taksimi nasıldır?", "en": "How are the attached rafʿ pronouns divided?"},
  "a": {"tr": "Müstetir ve bâriz. Müstetir de vâcibü'l-istitâr ve câizü'l-istitâr. Vâcip olanlar: mâzî dışında müfred müzekker muhâtab (تَضْرِبُ), mütekellim vahdeh (أَضْرِبُ) ve maa'l-gayr (نَضْرِبُ); emir mânâsındaki isim-fiiller (نَزَالِ = اِنْزِلْ); كُحُلْ meselesi dışında ism-i tafdîl (زَيْدٌ أَفْضَلُ مِنْ عَمْرٍو); zâhir fâilde amel şartları yokken ism-i fâil, ism-i mef'ûl, bu mânâdaki müsteâr ve mensûb isimler, sıfat-ı müşebbehe ve zarf-ı müstekar (جَاءَنِي ضَارِبٌ، جَاءَنِي أَسَدٌ نَاطِقٌ); mutlak olarak ism-i fâil ve ism-i mef'ûlün tesniye ve cem'leri (جَاءَنِي رَجُلَانِ ضَارِبَانِ); istisnâdaki عَدَا، خَلَا، مَا عَدَا، مَا خَلَا، لَيْسَ، لَا يَكُونُ (جَاءَنِي الْقَوْمُ عَدَا زَيْدًا). Câiz olanlar: zâhir isme isnad edilmeyen mâzî ve muzârinin müfred gâib ve gâibesi (زَيْدٌ ضَرَبَ، هِنْدٌ تَضْرِبُ); amel şartları varken tesniye ve cem' dışı şibh-i fiiller (زَيْدٌ ضَارِبٌ، زَيْدٌ هَاشِمِيٌّ، زَيْدٌ حَسَنٌ). Bâriz muttasıl: tesniyede elif, cem'-i müzekkerde vâv, cem'-i müenneste nûn; mâzînin müfred muhâtab, muhâtaba ve mütekellim vahdehinde tâ, maa'l-gayrda نَا; muzârinin müfred muhâtabasında yâ.",
        "en": "Hidden and apparent; the hidden is either necessarily or optionally hidden. Necessarily: outside the past, the 2nd masc. sing. (تَضْرِبُ), the 1st sing. (أَضْرِبُ) and plural (نَضْرِبُ); noun-verbs of command (نَزَالِ = اِنْزِلْ); the elative apart from the كُحُلْ case (زَيْدٌ أَفْضَلُ مِنْ عَمْرٍو); the active and passive participles, the borrowed and relative nouns in their sense, the ṣifa mushabbaha and the ẓarf mustaqarr when the conditions for governing an overt doer are absent (جَاءَنِي ضَارِبٌ، جَاءَنِي أَسَدٌ نَاطِقٌ); the dual and plural of the participles absolutely (جَاءَنِي رَجُلَانِ ضَارِبَانِ); and عَدَا، خَلَا، مَا عَدَا، مَا خَلَا، لَيْسَ، لَا يَكُونُ in exception (جَاءَنِي الْقَوْمُ عَدَا زَيْدًا). Optionally: the 3rd sing. masc. and fem. of the past and present not predicated of an overt noun (زَيْدٌ ضَرَبَ، هِنْدٌ تَضْرِبُ); the verb-like words, outside dual and plural, when the conditions for governing hold (زَيْدٌ ضَارِبٌ، زَيْدٌ هَاشِمِيٌّ، زَيْدٌ حَسَنٌ). Apparent attached: the alif of the dual, the wāw of the masc. plural, the nūn of the fem. plural; the tāʾ of the past's 2nd sing. masc. and fem. and 1st sing., نَا for the 1st plural; the yāʾ of the present's 2nd fem. sing."},
  "ar": ["زَيْدٌ أَفْضَلُ مِنْ عَمْرٍو", "جَاءَنِي أَسَدٌ نَاطِقٌ", "جَاءَنِي رَجُلَانِ ضَارِبَانِ", "هِنْدٌ تَضْرِبُ"], "notes": ["al-fail-al-mudmar-al-mustatir-wujuban", "al-mustatir-jawazan", "al-bariz-al-muttasil"]},
 {"n": 7, "q": {"tr": "Zamirin muttasıl olması ne zaman mazur görülür?", "en": "When is a pronoun excused from being attached?"},
  "a": {"tr": "Altı yerde: âmilinin önüne geçerse (إِيَّاكَ ضَرَبْتَ); bir garaz için âmiliyle arası ayrılırsa (مَا ضَرَبَكَ إِلَّا أَنَا); âmili hazfedilirse (إِيَّاكَ وَالشَّرَّ); âmili manevî âmil olursa (أَنَا زَيْدٌ); merfû zamir olup âmili harf olursa (مَا أَنْتَ قَائِمًا); kendisine «sahibinden başkasına cereyan eden sıfat» isnad edilirse (هِنْدٌ زَيْدٌ ضَارِبَتُهُ هِيَ).",
        "en": "In six places: when it precedes its governor (إِيَّاكَ ضَرَبْتَ); when something is set between them for a purpose (مَا ضَرَبَكَ إِلَّا أَنَا); when its governor is dropped (إِيَّاكَ وَالشَّرَّ); when its governor is one of meaning (أَنَا زَيْدٌ); when a rafʿ pronoun's governor is a particle (مَا أَنْتَ قَائِمًا); and when an adjective running on other than its owner is predicated of it (هِنْدٌ زَيْدٌ ضَارِبَتُهُ هِيَ)."},
  "ar": ["إِيَّاكَ ضَرَبْتَ", "مَا ضَرَبَكَ إِلَّا أَنَا", "إِيَّاكَ وَالشَّرَّ", "هِنْدٌ زَيْدٌ ضَارِبَتُهُ هِيَ"], "notes": ["mawadi-al-munfasil-wa-damir-al-fasl-wal-shan", "al-mabni-wal-mudmar"], "story": "al-kafiya", "chapter": 4},
 {"n": 8, "q": {"tr": "Nûn-ı vikâye nedir? Nerelerde lâzımdır?", "en": "What is the nūn of protection, and where is it required?"},
  "a": {"tr": "Kelimenin sonunu kesreden korumak için mütekellim yâ'sıyla birlikte gelen nûndur. Mâzîde ve i'râb nûnu bulunmayan muzâride lâzımdır (ضَرَبَنِي، يَضْرِبُنِي). İ'râb nûnu bulunan muzâride, لَدُنْ'de, إِنَّ ve kardeşlerinde getirilmesi de getirilmemesi de câizdir; لَيْتَ، عَنْ، قَدْ، قَطُّ'ta getirilmesi, لَعَلَّ'de getirilmemesi muhtardır.",
        "en": "The nūn that comes with the speaker's yāʾ to guard the word's end from the kasra. Required on the past verb and on a present without the nūn of iʿrāb (ضَرَبَنِي، يَضْرِبُنِي). Optional on a present with the nūn of iʿrāb, on لَدُنْ, on إِنَّ and its sisters; preferred on لَيْتَ، عَنْ، قَدْ، قَطُّ, and dispreferred on لَعَلَّ."},
  "ar": ["ضَرَبَنِي", "يَضْرِبُنِي"], "notes": ["ya-al-mutakallim", "al-mabni-wal-mudmar"], "story": "al-kafiya", "chapter": 4},
 {"n": 9, "q": {"tr": "Zamir-i fasl nedir? Şartı nedir? İ'râbdan mahalli var mıdır?", "en": "What is the pronoun of separation, what is its condition, and has it a place in iʿrāb?"},
  "a": {"tr": "Haberi sıfattan ayırmak için mübtedaya uygun olarak mübteda ile haber arasına gelen merfû zamirdir (زَيْدٌ هُوَ الْقَائِمُ). Şartı: haberin ma'rife ya da أَفْعَلُ مِنْ كَذَا cinsinden olması. Halîl'e göre i'râbdan mahalli yoktur; bazı Araplar onu mübteda, sonrasını haberi kılar.",
        "en": "A rafʿ pronoun set between mubtadaʾ and khabar, agreeing with the mubtadaʾ, to part the khabar from an adjective (زَيْدٌ هُوَ الْقَائِمُ). Its condition: the khabar is definite or of the kind أَفْعَلُ مِنْ كَذَا. For al-Khalīl it has no place in iʿrāb; some Arabs make it a mubtadaʾ with what follows as its khabar."},
  "ar": ["زَيْدٌ هُوَ الْقَائِمُ"], "notes": ["damir-fasl", "mawadi-al-munfasil-wa-damir-al-fasl-wal-shan"], "story": "al-kafiya", "chapter": 4},
 {"n": 10, "q": {"tr": "Zamir-i şân ve zamir-i kıssa nedir? Kaç kısımdır? Hazfi câiz midir?", "en": "What are the pronouns of the matter (shaʾn) and the story (qiṣṣa), how many kinds, and may they be dropped?"},
  "a": {"tr": "Cümlenin önüne geçip cümleyle tefsir edilen gâib zamiridir; müzekkerse şân, müennesse kıssa adını alır. Muttasıl (كَانَ زَيْدٌ قَائِمٌ'daki gizli zamir) ve munfasıl (هُوَ زَيْدٌ قَائِمٌ) olur. Mansûb olduğunda hazfi zayıf olmakla birlikte câizdir; şeddesiz meftûh أَنْ ile beraberse hazfi lâzımdır.",
        "en": "An absent pronoun standing before a sentence and explained by it — of the matter when masculine, of the story when feminine. Attached (the hidden pronoun of كَانَ زَيْدٌ قَائِمٌ) or detached (هُوَ زَيْدٌ قَائِمٌ). In naṣb it may be dropped, though weakly; with the lightened أَنْ it must be."},
  "ar": ["هُوَ زَيْدٌ قَائِمٌ"], "notes": ["mawadi-al-munfasil-wa-damir-al-fasl-wal-shan", "masail-inna-wal-mukhaffafa-fil-kafiya"], "story": "al-kafiya", "chapter": 4},
 {"n": 11, "q": {"tr": "İşaret isminin tarifi nedir?", "en": "How is the demonstrative defined?"},
  "a": {"tr": "Müşârun ileyh (kendisine işaret edilen) için konulan şeydir.", "en": "What is coined for the thing pointed at."},
  "ar": ["مَا وُضِعَ لِمُشَارٍ إِلَيْهِ"], "notes": ["asma-al-ishara", "asma-al-ishara-wa-sighuha"], "story": "al-kafiya", "chapter": 5},
 {"n": 12, "q": {"tr": "İşaret isimlerinden ذَا، ذَلِكَ ve ذَاكَ niçin kullanılır?", "en": "What are ذَا, ذَلِكَ and ذَاكَ used for?"},
  "a": {"tr": "ذَا yakın, ذَلِكَ uzak, ذَاكَ orta için.", "en": "ذَا for the near, ذَلِكَ for the far, ذَاكَ for the middle distance."},
  "ar": ["ذَا", "ذَاكَ", "ذَلِكَ"], "notes": ["asma-al-ishara", "asma-al-ishara-wa-sighuha"], "story": "al-kafiya", "chapter": 5},
 {"n": 13, "q": {"tr": "İsm-i mevsûlün tarifi nedir? Sılası nedir?", "en": "How is the relative defined, and what is its ṣila?"},
  "a": {"tr": "Cüz bakımından tamam olmayıp ancak sıla ve âid ile tamam olandır. Sılası ya haber cümlesidir ya da ism-i fâil ve ism-i mef'ûl gibi haber cümlesi yerine geçen şeylerdir.",
        "en": "What is not complete as a part except by a ṣila and a returning pronoun. Its ṣila is a declarative sentence or what stands for one, like the active and passive participles."},
  "ar": ["مَا لَا يَتِمُّ جُزْءًا إِلَّا بِصِلَةٍ وَعَائِدٍ"], "notes": ["ism-mawsul", "asma-al-ishara-wal-mawsulat"], "story": "al-kafiya", "chapter": 5},
 {"n": 14, "q": {"tr": "Âid nedir? Ism-i fâil ve ism-i mef'ûlün sılası nedir?", "en": "What is the returning pronoun, and what is the ṣila of the participles?"},
  "a": {"tr": "Sıladan ism-i mevsûle dönen zamirdir; çoğu kullanımda zamirden başka olmaz, nadiren zamir yerine zâhir isim gelir (جَاءَنِي زَيْدٌ الَّذِي ضَرَبَ زَيْدٌ). Mevsûl olan elif-lâmın sılası ism-i fâil ve ism-i mef'ûldür.",
        "en": "The pronoun in the ṣila that points back at the relative; nearly always a pronoun, rarely an overt noun in its place (جَاءَنِي زَيْدٌ الَّذِي ضَرَبَ زَيْدٌ). The ṣila of the relative article is the active or passive participle."},
  "ar": ["جَاءَنِي زَيْدٌ الَّذِي ضَرَبَ زَيْدٌ"], "notes": ["ism-mawsul", "al-mawsul-wal-muarraf-bil-lam-wal-mudaf"], "story": "al-kafiya", "chapter": 5},
 {"n": 15, "q": {"tr": "İsm-i mevsûller nelerdir?", "en": "Which are the relatives?"},
  "a": {"tr": "الَّذِي ve الَّتِي ile tesniye ve cem'leri; bunlarla birlikte الَّذِي mânâsına مَا، مَنْ، أَيُّ; الَّتِي mânâsına أَيَّةٌ; Tay kabilesinde ذُو; istifham مَا'sından sonra gelen ذَا; ve elif-lâm.",
        "en": "الَّذِي and الَّتِي with their duals and plurals; with them مَا، مَنْ، أَيُّ in the sense of الَّذِي, أَيَّةٌ in the sense of الَّتِي; ذُو among the tribe of Ṭayy; ذَا after interrogative مَا; and the article."},
  "ar": [], "notes": ["ism-mawsul", "asma-al-ishara-wal-mawsulat", "anwa-ma"], "story": "al-kafiya", "chapter": 5},
 {"n": 16, "q": {"tr": "الَّذِي ile haber vermek için kaç şart vardır?", "en": "What is required to predicate with الَّذِي?"},
  "a": {"tr": "Üç şart: الَّذِي cümlenin başına geçirilir; muhberün anhın yerine الَّذِي'ye dönen bir zamir konur; muhberün anh الَّذِي'nin haberi olarak sona bırakılır. ضَرَبْتُ زَيْدًا cümlesinde زَيْد'den haber verilecekse: الَّذِي ضَرَبْتُهُ زَيْدٌ.",
        "en": "Three: الَّذِي is moved to the head; a pronoun pointing at it replaces the thing predicated of; and that thing is put last as the khabar. To predicate of زَيْد in ضَرَبْتُ زَيْدًا: الَّذِي ضَرَبْتُهُ زَيْدٌ."},
  "ar": ["الَّذِي ضَرَبْتُهُ زَيْدٌ"], "notes": ["ism-mawsul"]},
 {"n": 17, "q": {"tr": "İsim olan مَا ve مَنْ hangi mânâlara gelir?", "en": "What senses do nominal مَا and مَنْ carry?"},
  "a": {"tr": "مَا: kâffe, nâfiye, mevsûle, istifhâmiyye, şartiyye, mevsûfe, «şey» mânâsına tâmme, sıfat. مَنْ de مَا'nın mânâlarına gelir; yalnız tâmme ve sıfat mânâlarına gelmez.",
        "en": "مَا: restraining, negating, relative, interrogative, conditional, described, complete in the sense of «a thing», and adjectival. مَنْ carries the same senses except the complete and the adjectival."},
  "ar": [], "notes": ["anwa-ma", "hal-ma-man", "ism-mawsul"], "story": "al-kafiya", "chapter": 5},
 {"n": 18, "q": {"tr": "İsim-fiillerin tarifi nedir?", "en": "How are the noun-verbs defined?"},
  "a": {"tr": "Emir ya da mâzî mânâsında olan isimdir. Mâzî mânâsına: هَيْهَاتَ ذَاكَ (هَيْهَاتَ = بَعُدَ); emir mânâsına: رُوَيْدَ زَيْدًا (رُوَيْدَ = أَمْهِلْهُ).",
        "en": "A noun with the sense of a command or of a past verb. Of the past: هَيْهَاتَ ذَاكَ (هَيْهَاتَ = بَعُدَ); of command: رُوَيْدَ زَيْدًا (رُوَيْدَ = أَمْهِلْهُ)."},
  "ar": ["مَا كَانَ بِمَعْنَى الْأَمْرِ أَوِ الْمَاضِي", "هَيْهَاتَ ذَاكَ", "رُوَيْدَ زَيْدًا"], "notes": ["ism-fil", "asma-al-afal-wal-aswat-wal-murakkabat", "mana-al-fil-wa-asma-al-afal"], "story": "al-kafiya", "chapter": 6},
 {"n": 19, "q": {"tr": "İsim-fiiller nelerdir?", "en": "Which are the noun-verbs?"},
  "a": {"tr": "Sülâsî mücerredden emir mânâsındaki فَعَالِ vezni kıyâsîdir. فَعَالِ vezninde ma'rife masdarlar (فَجَارِ) ve müennesin sıfatı olan masdarlar (فَسَاقِ), emir mânâsındakine adl ve vezince benzerlikle mebnîdir. Ayn için müennese alem olan فَعَالِ ise Hicaz ehline göre mebnî, Benî Temîm'e göre mu'rabdır.",
        "en": "From the bare triliteral, فَعَالِ in the sense of a command is regular. Definite masdars on فَعَالِ (فَجَارِ) and masdars that are adjectives of the feminine (فَسَاقِ) are built by likeness, in deviation and pattern, to the command type. فَعَالِ as a feminine proper name of a concrete thing is built for the Ḥijāzīs and declined for the Banū Tamīm."},
  "ar": ["فَجَارِ", "فَسَاقِ"], "notes": ["ism-fil", "asma-al-afal-wal-aswat-wal-murakkabat"], "story": "al-kafiya", "chapter": 6},
 {"n": 20, "q": {"tr": "Seslerin (asvât) tarifi nedir?", "en": "How are the sounds (aṣwāt) defined?"},
  "a": {"tr": "Kendisiyle bir ses hikâye edilen ya da hayvanlara seslenilen her lafızdır. Ses hikâyesine misal: insanın kendini kargaya benzeterek غَاقْ demesi; hayvana seslenmeye misal: deveye نَخْ demesi.",
        "en": "Every word by which a sound is imitated or an animal is called. Imitation: a person's غَاقْ, mimicking a crow; calling: نَخْ to a camel."},
  "ar": ["كُلُّ لَفْظٍ حُكِيَ بِهِ صَوْتٌ أَوْ صُوِّتَ بِهِ لِلْبَهَائِمِ"], "notes": ["asma-al-afal-wal-aswat-wal-murakkabat"], "story": "al-kafiya", "chapter": 6},
 {"n": 21, "q": {"tr": "Mürekkebâtın tarifi nedir? Nasıl mebnî kılınır?", "en": "How are the compounds defined, and how are they built?"},
  "a": {"tr": "Aralarında nisbet bulunmayan iki kelimeden meydana gelen her isimdir. İkinci cüz harf mânâsı taşırsa iki cüz de mebnî kılınır (خَمْسَةَ عَشَرَ، حَادِيَ عَشَرَ ve kardeşleri); yalnız اثْنَا عَشَرَ'nin ikinci cüzü mebnîdir. İkinci cüz harf mânâsı taşımazsa gayr-i munsarif olarak mu'rab, birinci cüz mebnî olur (بَعْلَبَكُّ).",
        "en": "Every noun made of two words with no attribution between them. When the second part carries a particle's meaning both parts are built (خَمْسَةَ عَشَرَ، حَادِيَ عَشَرَ and their sisters); in اثْنَا عَشَرَ only the second part is built. When it does not, the second part is declined as a diptote and the first is built (بَعْلَبَكُّ)."},
  "ar": ["كُلُّ اسْمٍ مِنْ كَلِمَتَيْنِ لَيْسَ بَيْنَهُمَا نِسْبَةٌ", "خَمْسَةَ عَشَرَ", "بَعْلَبَكُّ"], "notes": ["al-mabni-al-lazim-al-murakkab-al-adadi-wa-bayta-bayta-wa-ithna-ashar", "asma-al-afal-wal-aswat-wal-murakkabat"], "story": "al-kafiya", "chapter": 6},
 {"n": 22, "q": {"tr": "Kinâyâtın tarifi nedir? Kinâyeler nelerdir?", "en": "How are the allusive nouns (kināyāt) defined, and which are they?"},
  "a": {"tr": "Bir maksatla, delâleti açık olmayan bir lafızla belirli bir şeyden ta'bir etmektir. كَمْ ve كَذَا sayı için; كَيْتَ ve ذَيْتَ söz (hadîs) içindir.", "en": "Expressing a definite thing, for some purpose, by a word that does not point at it plainly. كَمْ and كَذَا are for number; كَيْتَ and ذَيْتَ for speech."},
  "ar": ["وَهِيَ أَنْ يُعَبَّرَ عَنْ شَيْءٍ مُعَيَّنٍ بِلَفْظٍ غَيْرِ صَرِيحٍ فِي الدَّلَالَةِ عَلَيْهِ لِغَرَضٍ مِنَ الْأَغْرَاضِ"], "notes": ["al-kinayat-wal-zuruf-al-mabniyya"], "story": "al-kafiya", "chapter": 7},
]
